use vstd::prelude::*;

verus! {

/// Reverse a vector of i8s.
/// 
/// Ensures:
///   - The returned vector has the same length as the input.
///   - For all valid k, rev[k] = s[n-1-k].
fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev.len() == s.len(),
        forall |k: usize| k < s.len() ==> rev.index(k) == s.index(s.len() - 1 - k),
{
    let n: usize = s.len();
    // Start with an empty vector, reserve the needed capacity
    let mut rev: Vec<i8> = Vec::new();
    rev.reserve(n);

    let mut i: usize = 0;
    // Build rev by pushing s[n-1-i] for i = 0 .. n
    while i < n
        invariant
            // i never exceeds n
            i <= n,
            // rev has exactly i elements
            rev.len() == i,
            // For each pushed element k < i, rev[k] = s[n-1-k]
            forall |k: usize| k < i ==> rev.index(k) == s.index(n - 1 - k),
        decreases n - i,
    {
        // Read the element from the end of s
        let elem: i8 = s.index(n - 1 - i);
        rev.push(elem);
        i += 1;
    }

    rev
}

} // verus!

